import React, { useState } from "react";
import { Card, Button } from "react-bootstrap";

const token = "6tySK2p9ZxyKAySWyyNU";
const privateIp = "http://192.168.0.220:32400/library/sections/";
const libraries = {
  movie: 1,
  show: 2,
  music: 3,
};

const Plex = () => {
  const [urTextKey, setUrTextKey] = useState();
  const clickHandler = (e, setUrTextKey) => {
    fetch(privateIp, {
      headers: { Accept: "application/json", "X-Plex-Token": token },
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error("Network Response Failure");
        }
        return response.json();
      })
      .then((data) => {
        console.log(data);
        let directories = data.MediaContainer.Directory;
        for (var i = 0; i < directories.length; i++) {
          let directory = directories[i];
          console.log(directory);
          if (directory.title === "UrText") {
            setUrTextKey(directory.key);
            console.log("UrText Set as: " + directory.key);
          }
        }
      })
      .catch((error) => {
        console.log("Error: ", error);
      });
  };
  return (
    <>
      <Button
        onClick={(e) => {
          clickHandler(e, setUrTextKey);
        }}
      >
        Click here for UrText
      </Button>
    </>
  );
};

export default Plex;
